 void UpdateLive(){if(audioStatus!=null)audioStatus.Text=L10n.Text(state["audio"]?.GetValue<string>()??"Conectando audio");int rate=state["sampleRate"]?.GetValue<int>()??0,fft=state["fft"]?.GetValue<int>()??0;if(fftStatus!=null)fftStatus.Text=L10n.Text($"64 bandas · FFT {fft} · {(fft>0?rate/(double)fft:0):0.00} Hz/bin · análisis 0–{rate/2:N0} Hz");if(audioButton!=null)audioButton.Content=L10n.Text(state["audioRunning"]?.GetValue<bool>()==true?"Detener captura":"Activar audio del sistema");var bands=state["bands"]?.AsArray();bool fresh=(state["age"]?.GetValue<double>()??99)<.4&&state["audioRunning"]?.GetValue<bool>()==true;for(int i=0;i<64;i++)if(audioStatus!=null&&meters[i]!=null){meters[i].Height=Math.Clamp(fresh&&bands!=null&&i<bands.Count?(bands[i]?.GetValue<double>()??0)*52:2,2,54);meters[i].Opacity=fresh ? .85 : .2;}if(tempo!=null){double bpm=state["bpm"]?.GetValue<double>()??0;tempo.Text=L10n.Text(bpm>0?$"{bpm:0} BPM":"Esperando un ritmo estable");}if(mediaStatus!=null)mediaStatus.Text=L10n.Text(state["media"]?.GetValue<string>()??"");if(performance!=null)performance.Text=string.Join("\n",state["performance"]?.AsArray().OfType<JsonObject>().Select(p=>$"{p["name"]}: {p["fps"]?.GetValue<double>():0} FPS / {p["target"]?.GetValue<double>():0} · {p["drawMs"]?.GetValue<double>():0.00} ms\n{p["backend"]}")??[]);}
